"use client";

import type { PostActivityDto, PostId } from "afferent";
import { usePostActivity, type PostActivityState } from "afferent/react.js";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentPostActivity({ postId }: Readonly<{ postId: PostId }>) {
  return <AfferentPostActivityView state={usePostActivity(postId)} />;
}

export function AfferentPostActivityView({
  state,
}: Readonly<{ state: PostActivityState }>) {
  const { copy } = useAfferentUi();
  switch (state.status) {
    case "unsupported":
    case "empty": {
      return null;
    }
    case "loading": {
      return <AfferentStateRegion title={copy.activity.loading} />;
    }
    case "error": {
      return null;
    }
    case "ready": {
      return (
        <section
          className="afferent-activity"
          aria-labelledby="afferent-activity-heading"
        >
          <h2 id="afferent-activity-heading">{copy.activity.heading}</h2>
          <ol>
            {state.items.map((item) => (
              <li key={item.id}>{activityLabel(item, copy.activity)}</li>
            ))}
          </ol>
          {state.canLoadMore ? (
            <button
              type="button"
              onClick={state.loadMore}
              disabled={state.isLoadingMore}
            >
              {state.isLoadingMore
                ? copy.activity.loadingMore
                : copy.activity.loadMore}
            </button>
          ) : null}
        </section>
      );
    }
    default: {
      return assertNever(state.status);
    }
  }
}

function activityLabel(
  item: PostActivityDto,
  copy: ReturnType<typeof useAfferentUi>["copy"]["activity"],
) {
  return copy.event(item.type, item.actor?.displayName);
}

"use client";

import { useId, useState } from "react";
import type { BoardDto, PostId, PostStatusKey } from "afferent";
import {
  useFeedbackFeed,
  useFeedbackSearch,
  type FeedbackFeedArgs,
  type FeedbackFeedState,
  type BoundedDiscoveryState,
} from "afferent/react.js";

import { AfferentFeedbackComposer } from "@/components/afferent/board/feedback-composer";
import { AfferentFeedbackList } from "@/components/afferent/board/feedback-list";
import { AfferentPostDetail } from "@/components/afferent/board/post-detail";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  afferentErrorText,
  assertNever,
} from "@/components/afferent/core/state-region";

export type AfferentBoardScreenProps = Readonly<{
  boards?: readonly BoardDto[];
  feedArgs?: FeedbackFeedArgs;
  pageOwner?: boolean;
  postId?: PostId;
  title?: string;
}>;

export function AfferentBoardScreen({
  boards = [],
  feedArgs = { order: "top" },
  pageOwner = true,
  postId,
  title,
}: AfferentBoardScreenProps) {
  const [boardId, setBoardId] = useState<BoardDto["id"] | undefined>(
    feedArgs.boardId ?? boards[0]?.id,
  );
  const [order, setOrder] = useState(feedArgs.order);
  const [status, setStatus] = useState<PostStatusKey | undefined>(
    feedArgs.status,
  );
  const [query, setQuery] = useState("");
  const [composing, setComposing] = useState(false);
  const feed = useFeedbackFeed({
    order,
    boardId,
    status,
    tagId: feedArgs.tagId,
  });
  const search = useFeedbackSearch({
    query,
    boardId,
    status,
    tagId: feedArgs.tagId,
    debounceMs: 0,
  });
  return (
    <AfferentBoardView
      boards={boards}
      boardId={boardId}
      order={order}
      status={status}
      query={query}
      feed={feed}
      search={search}
      composing={composing}
      postId={postId}
      pageOwner={pageOwner}
      title={title}
      onBoardChange={setBoardId}
      onOrderChange={setOrder}
      onStatusChange={setStatus}
      onQueryChange={setQuery}
      onComposingChange={setComposing}
    />
  );
}

type BoardViewProps = Readonly<{
  boards?: readonly BoardDto[];
  boardId?: BoardDto["id"];
  order?: FeedbackFeedArgs["order"];
  status?: PostStatusKey;
  query?: string;
  feed: FeedbackFeedState;
  search?: BoundedDiscoveryState;
  composing?: boolean;
  pageOwner?: boolean;
  title?: string;
  postId?: PostId;
  onBoardChange?: (boardId: BoardDto["id"] | undefined) => void;
  onOrderChange?: (order: FeedbackFeedArgs["order"]) => void;
  onStatusChange?: (status: PostStatusKey | undefined) => void;
  onQueryChange?: (query: string) => void;
  onComposingChange?: (composing: boolean) => void;
}>;

export function AfferentBoardView({
  boards = [],
  boardId,
  order = "top",
  status,
  query = "",
  feed,
  search,
  composing = false,
  pageOwner = true,
  title,
  postId,
  onBoardChange,
  onOrderChange,
  onStatusChange,
  onQueryChange,
  onComposingChange,
}: BoardViewProps) {
  const { copy, icons } = useAfferentUi();
  const controlsId = useId();
  const boardControlId = `${controlsId}-board`;
  const searchControlId = `${controlsId}-search`;
  const statusControlId = `${controlsId}-status`;
  const sortControlId = `${controlsId}-sort`;
  const searching = query.trim().length > 0;

  const content =
    searching && search ? renderSearch(search, copy) : renderFeed(feed, copy);
  const body = (
    <div className="afferent-board" data-afferent-screen="board">
      <header className="afferent-board__header">
        <div>
          <h1>{title ?? copy.board.title}</h1>
          <p>{copy.board.description}</p>
        </div>
        <button
          type="button"
          className="afferent-button"
          onClick={() => onComposingChange?.(!composing)}
        >
          <icons.create aria-hidden="true" />
          {copy.board.createFeedback}
        </button>
      </header>
      <section
        className="afferent-board__controls"
        aria-labelledby={controlsId}
      >
        <h2 id={controlsId}>{copy.board.browseHeading}</h2>
        <div className="afferent-controls-grid">
          <label htmlFor={boardControlId}>
            {copy.board.boardLabel}
            <select
              id={boardControlId}
              name="board"
              value={boardId ?? ""}
              onChange={(event) =>
                onBoardChange?.(
                  event.currentTarget.value
                    ? (event.currentTarget.value as BoardDto["id"])
                    : undefined,
                )
              }
            >
              <option value="">{copy.board.allBoards}</option>
              {boards.map((board) => (
                <option key={board.id} value={board.id}>
                  {board.name}
                </option>
              ))}
            </select>
          </label>
          <label htmlFor={searchControlId}>
            {copy.board.searchLabel}
            <input
              id={searchControlId}
              type="search"
              name="search"
              value={query}
              onChange={(event) => onQueryChange?.(event.currentTarget.value)}
            />
          </label>
          <label htmlFor={statusControlId}>
            {copy.board.statusLabel}
            <select
              id={statusControlId}
              name="status"
              value={status ?? ""}
              onChange={(event) =>
                onStatusChange?.(
                  event.currentTarget.value
                    ? (event.currentTarget.value as PostStatusKey)
                    : undefined,
                )
              }
            >
              <option value="">{copy.board.allStatuses}</option>
              <option value="open">Open</option>
              <option value="under_review">Under Review</option>
              <option value="planned">Planned</option>
              <option value="in_progress">In Progress</option>
              <option value="complete">Complete</option>
              <option value="closed">Closed</option>
            </select>
          </label>
          <label htmlFor={sortControlId}>
            {copy.board.sortLabel}
            <select
              id={sortControlId}
              name="sort"
              value={order}
              onChange={(event) =>
                onOrderChange?.(
                  event.currentTarget.value as FeedbackFeedArgs["order"],
                )
              }
            >
              <option value="top">Top</option>
              <option value="newest">Newest</option>
              <option value="trending">Trending</option>
            </select>
          </label>
        </div>
        {searching ? (
          <button
            type="button"
            className="afferent-button afferent-button--secondary"
            onClick={() => {
              onQueryChange?.("");
              onStatusChange?.(undefined);
            }}
          >
            {copy.board.clearFilters}
          </button>
        ) : null}
      </section>
      {composing ? (
        <AfferentFeedbackComposer
          boardId={boardId}
          onClose={() => onComposingChange?.(false)}
        />
      ) : null}
      <div className={postId ? "afferent-board__workspace" : undefined}>
        <section
          className="afferent-board__results"
          aria-labelledby="afferent-results-heading"
        >
          <h2 id="afferent-results-heading">{copy.board.resultsHeading}</h2>
          {content}
        </section>
        {postId ? <AfferentPostDetail postId={postId} /> : null}
      </div>
    </div>
  );
  if (!pageOwner) return body;
  return (
    <>
      <a className="afferent-skip-link" href="#afferent-board-main">
        {copy.board.skipToFeedback}
      </a>
      <main id="afferent-board-main">{body}</main>
    </>
  );
}

function renderFeed(
  feed: FeedbackFeedState,
  copy: ReturnType<typeof useAfferentUi>["copy"],
) {
  switch (feed.status) {
    case "loading": {
      return <AfferentStateRegion title={`${copy.common.loading} feedback…`} />;
    }
    case "empty": {
      return (
        <AfferentStateRegion title={copy.board.emptyHeading}>
          <p>{copy.board.emptyBody}</p>
        </AfferentStateRegion>
      );
    }
    case "error": {
      return (
        <AfferentStateRegion title={copy.board.loadErrorHeading} tone="error">
          <p>{copy.board.loadErrorBody}</p>
          <p>{afferentErrorText(feed.error)}</p>
          <button type="button" onClick={feed.loadMore}>
            {copy.common.tryLoadingAgain}
          </button>
        </AfferentStateRegion>
      );
    }
    case "ready": {
      return (
        <>
          <AfferentFeedbackList items={feed.items} />
          {feed.canLoadMore ? (
            <button
              type="button"
              className="afferent-button afferent-button--secondary"
              onClick={feed.loadMore}
              disabled={feed.isLoadingMore}
              aria-busy={feed.isLoadingMore}
            >
              {feed.isLoadingMore
                ? copy.board.loadingMore
                : copy.board.loadMore}
            </button>
          ) : null}
          <p className="afferent-sr-only" role="status" aria-live="polite">
            {feed.isLoadingMore
              ? copy.board.loadingMore
              : copy.board.resultCount(feed.items.length)}
          </p>
        </>
      );
    }
    default: {
      return assertNever(feed);
    }
  }
}

function renderSearch(
  state: BoundedDiscoveryState,
  copy: ReturnType<typeof useAfferentUi>["copy"],
) {
  switch (state.status) {
    case "unsupported": {
      return (
        <AfferentStateRegion title={copy.common.unsupportedHeading}>
          <p>{copy.common.unsupportedBody}</p>
        </AfferentStateRegion>
      );
    }
    case "loading": {
      return <AfferentStateRegion title={copy.board.loadingSearch} />;
    }
    case "empty": {
      return (
        <AfferentStateRegion title={copy.board.noMatchesHeading}>
          <p>{copy.board.noMatchesBody}</p>
        </AfferentStateRegion>
      );
    }
    case "error": {
      return (
        <AfferentStateRegion title={copy.board.searchErrorHeading} tone="error">
          <p>{afferentErrorText(state.error)}</p>
        </AfferentStateRegion>
      );
    }
    case "ready": {
      return (
        <>
          <AfferentFeedbackList
            items={state.items}
            label={copy.board.searchResultsLabel}
          />
          <p className="afferent-sr-only" role="status">
            {copy.board.resultCount(state.items.length)}
          </p>
        </>
      );
    }
    default: {
      return assertNever(state);
    }
  }
}

"use client";

import { useId, useState, type FormEvent } from "react";
import type { CommentId, PostId } from "afferent";
import {
  feedbackMutationKey,
  useComments,
  useFeedbackMutations,
  type CommentFeedState,
} from "afferent/react.js";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  afferentErrorText,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentDiscussion({ postId }: Readonly<{ postId: PostId }>) {
  const comments = useComments(postId);
  const mutations = useFeedbackMutations();
  return (
    <AfferentDiscussionView
      postId={postId}
      comments={comments}
      mutationStatus={mutations.status}
      pending={
        mutations.pending[feedbackMutationKey(postId, "comment")] ?? false
      }
      error={mutations.errors[feedbackMutationKey(postId, "comment")]}
      addComment={mutations.addComment}
      resetError={() => mutations.reset(feedbackMutationKey(postId, "comment"))}
    />
  );
}

export function AfferentDiscussionView({
  postId,
  comments,
  mutationStatus,
  pending,
  error,
  addComment,
  resetError,
}: Readonly<{
  postId: PostId;
  comments: CommentFeedState;
  mutationStatus: ReturnType<typeof useFeedbackMutations>["status"];
  pending: boolean;
  error: ReturnType<typeof useFeedbackMutations>["errors"][string];
  addComment: ReturnType<typeof useFeedbackMutations>["addComment"];
  resetError: () => void;
}>) {
  const { copy } = useAfferentUi();
  const [body, setBody] = useState("");
  const [replyingTo, setReplyingTo] = useState<CommentId | undefined>();
  const fieldId = useId();

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!body.trim()) return;
    await addComment({
      postId,
      body: body.trim(),
      ...(replyingTo ? { parentCommentId: replyingTo } : {}),
    });
  }

  const rows = (() => {
    switch (comments.status) {
      case "unsupported": {
        return (
          <AfferentStateRegion title={copy.common.unsupportedHeading}>
            <p>{copy.common.unsupportedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "loading": {
        return <AfferentStateRegion title={copy.discussion.loading} />;
      }
      case "empty": {
        return (
          <AfferentStateRegion title={copy.discussion.emptyHeading}>
            <p>{copy.discussion.emptyBody}</p>
          </AfferentStateRegion>
        );
      }
      case "error": {
        return (
          <AfferentStateRegion
            title={copy.discussion.loadErrorHeading}
            tone="error"
          >
            <p>{afferentErrorText(comments.error)}</p>
            {comments.items.length ? <CommentRows /> : null}
          </AfferentStateRegion>
        );
      }
      case "ready": {
        return <CommentRows />;
      }
      default: {
        return assertNever(comments);
      }
    }
  })();

  function CommentRows() {
    return (
      <ol className="afferent-discussion__list">
        {comments.items.map((comment) => (
          <li
            key={comment.id}
            data-comment-id={comment.id}
            data-parent-comment-id={comment.parentCommentId}
            className={
              comment.parentCommentId
                ? "afferent-comment afferent-comment--reply"
                : "afferent-comment"
            }
          >
            <article>
              <h3>
                {comment.author.displayName ?? copy.discussion.anonymousAuthor}
              </h3>
              <p>{comment.body}</p>
              {!comment.parentCommentId ? (
                <button type="button" onClick={() => setReplyingTo(comment.id)}>
                  {copy.discussion.reply}
                </button>
              ) : null}
            </article>
          </li>
        ))}
      </ol>
    );
  }

  let composer = null;
  if (mutationStatus === "unauthenticated") {
    composer = (
      <AfferentStateRegion title={copy.common.signInHeading}>
        <p>{copy.discussion.signInBody}</p>
      </AfferentStateRegion>
    );
  } else if (mutationStatus === "unsupported") {
    composer = (
      <AfferentStateRegion title={copy.common.unsupportedHeading}>
        <p>{copy.common.unsupportedBody}</p>
      </AfferentStateRegion>
    );
  } else if (mutationStatus === "loading") {
    composer = <AfferentStateRegion title={copy.common.loadingParticipation} />;
  } else {
    composer = (
      <form
        onSubmit={submit}
        aria-busy={pending}
        className="afferent-comment-form"
      >
        <label htmlFor={fieldId}>
          {replyingTo
            ? copy.discussion.replyLabel
            : copy.discussion.commentLabel}
        </label>
        <textarea
          id={fieldId}
          name={replyingTo ? "reply" : "comment"}
          value={body}
          onChange={(event) => setBody(event.currentTarget.value)}
          required
        />
        {error ? (
          <div role="alert">
            <p>{afferentErrorText(error)}</p>
            <button type="button" onClick={resetError}>
              {copy.common.dismissError}
            </button>
          </div>
        ) : null}
        <div className="afferent-actions">
          <button type="submit" className="afferent-button" disabled={pending}>
            {replyingTo
              ? copy.discussion.postReply
              : copy.discussion.postComment}
          </button>
          {replyingTo ? (
            <button
              type="button"
              className="afferent-button afferent-button--secondary"
              onClick={() => setReplyingTo(undefined)}
            >
              {copy.discussion.returnToCommenting}
            </button>
          ) : null}
        </div>
      </form>
    );
  }

  return (
    <section
      className="afferent-discussion"
      aria-labelledby="afferent-discussion-heading"
    >
      <h2 id="afferent-discussion-heading">{copy.discussion.heading}</h2>
      {rows}
      {comments.status === "ready" && comments.canLoadMore ? (
        <button
          type="button"
          onClick={comments.loadMore}
          disabled={comments.isLoadingMore}
          aria-busy={comments.isLoadingMore}
        >
          {comments.isLoadingMore
            ? copy.discussion.loadingMore
            : copy.discussion.loadMore}
        </button>
      ) : null}
      {composer}
    </section>
  );
}

import type { DiscoveryPostDto, FeedbackPostDto } from "afferent";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";

export function AfferentFeedbackCard({
  post,
}: Readonly<{ post: DiscoveryPostDto | FeedbackPostDto }>) {
  const { copy, icons, navigation } = useAfferentUi();
  const Link = navigation.Link;
  const detailed = "body" in post;
  return (
    <article className="afferent-feedback-card">
      <div className="afferent-feedback-card__content">
        <h2>
          <Link href={navigation.href.post(post.id)}>{post.title}</Link>
        </h2>
        {detailed ? (
          <p className="afferent-feedback-card__body">{post.body}</p>
        ) : null}
        <p className="afferent-feedback-card__status">{post.status.label}</p>
        <p className="afferent-feedback-card__board">{post.board.name}</p>
      </div>
      {detailed ? (
        <dl className="afferent-feedback-card__totals">
          <div>
            <dt>
              <icons.votes aria-hidden="true" /> Votes
            </dt>
            <dd>{copy.board.voteCount(post.voteCount)}</dd>
          </div>
          <div>
            <dt>
              <icons.comments aria-hidden="true" /> Comments
            </dt>
            <dd>{copy.board.commentCount(post.commentCount)}</dd>
          </div>
        </dl>
      ) : null}
    </article>
  );
}

"use client";

import { useId, useState, type FormEvent } from "react";
import type { BoardId } from "afferent";
import { feedbackMutationKey, useFeedbackMutations } from "afferent/react.js";

import { AfferentSimilarFeedback } from "@/components/afferent/board/similar-feedback";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  afferentErrorText,
} from "@/components/afferent/core/state-region";

export function AfferentFeedbackComposer({
  boardId,
  onClose,
}: Readonly<{ boardId?: BoardId; onClose: () => void }>) {
  const { copy } = useAfferentUi();
  const mutations = useFeedbackMutations();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const titleHelpId = useId();
  const bodyHelpId = useId();
  const key = feedbackMutationKey("post", "create");
  const pending = mutations.pending[key] ?? false;
  const error = mutations.errors[key];

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!boardId || title.trim().length === 0 || body.trim().length === 0)
      return;
    await mutations.createPost({
      boardId,
      title: title.trim(),
      body: body.trim(),
    });
  }

  if (mutations.status === "loading") {
    return (
      <AfferentStateRegion title={copy.common.loadingParticipation}>
        <p>{copy.board.createHelp}</p>
      </AfferentStateRegion>
    );
  }
  if (mutations.status === "unsupported") {
    return (
      <AfferentStateRegion title={copy.common.unsupportedHeading}>
        <p>{copy.common.unsupportedBody}</p>
      </AfferentStateRegion>
    );
  }
  if (mutations.status === "unauthenticated") {
    return (
      <AfferentStateRegion title={copy.common.signInHeading}>
        <p>{copy.board.signInToCreate}</p>
      </AfferentStateRegion>
    );
  }

  return (
    <section
      className="afferent-composer"
      aria-labelledby="afferent-composer-heading"
    >
      <h2 id="afferent-composer-heading">{copy.board.createFeedback}</h2>
      <p>{copy.board.createHelp}</p>
      <form data-afferent-composer onSubmit={submit} aria-busy={pending}>
        <div className="afferent-field">
          <label htmlFor="afferent-feedback-title">
            {copy.board.titleLabel}
          </label>
          <input
            id="afferent-feedback-title"
            name="title"
            value={title}
            onChange={(event) => setTitle(event.currentTarget.value)}
            aria-describedby={titleHelpId}
            required
          />
          <p id={titleHelpId}>{copy.board.titleHelp}</p>
        </div>
        <div className="afferent-field">
          <label htmlFor="afferent-feedback-body">{copy.board.bodyLabel}</label>
          <textarea
            id="afferent-feedback-body"
            name="body"
            value={body}
            onChange={(event) => setBody(event.currentTarget.value)}
            aria-describedby={bodyHelpId}
            required
          />
          <p id={bodyHelpId}>{copy.board.bodyHelp}</p>
        </div>
        {title.trim() ? (
          <AfferentSimilarFeedback title={title} body={body} />
        ) : null}
        {error ? (
          <div role="alert" className="afferent-inline-error">
            <h3>{copy.board.createErrorHeading}</h3>
            <p>{afferentErrorText(error)}</p>
            <button type="button" onClick={() => mutations.reset(key)}>
              {copy.common.dismissError}
            </button>
          </div>
        ) : null}
        <div className="afferent-actions">
          <button
            type="submit"
            className="afferent-button"
            disabled={pending || !boardId}
          >
            {copy.board.postFeedback}
          </button>
          <button
            type="button"
            className="afferent-button afferent-button--secondary"
            onClick={onClose}
          >
            {copy.board.returnToFeedback}
          </button>
        </div>
      </form>
      <p className="afferent-sr-only" role="status" aria-live="polite">
        {pending ? copy.board.postingFeedback : ""}
      </p>
    </section>
  );
}

import type { DiscoveryPostDto, FeedbackPostDto } from "afferent";

import { AfferentFeedbackCard } from "@/components/afferent/board/feedback-card";

export function AfferentFeedbackList({
  items,
  label = "Feedback",
}: Readonly<{
  items: readonly (DiscoveryPostDto | FeedbackPostDto)[];
  label?: string;
}>) {
  return (
    <ol className="afferent-board__list" aria-label={label}>
      {items.map((post) => (
        <li key={post.id}>
          <AfferentFeedbackCard post={post} />
        </li>
      ))}
    </ol>
  );
}

"use client";

import { useRef, useState, type FormEvent } from "react";
import type { FeedbackPostDto, PostId } from "afferent";
import {
  feedbackMutationKey,
  useFeedbackMutations,
  usePost,
  usePostSubscription,
  type PostLookupState,
} from "afferent/react.js";

import { AfferentPostActivity } from "@/components/afferent/board/activity";
import { AfferentDiscussion } from "@/components/afferent/board/discussion";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  afferentErrorText,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentPostDetail({ postId }: Readonly<{ postId: PostId }>) {
  const lookup = usePost(postId);
  return <AfferentPostDetailView lookup={lookup} />;
}

export function AfferentPostDetailView({
  lookup,
}: Readonly<{ lookup: PostLookupState }>) {
  const { copy, navigation } = useAfferentUi();
  const Link = navigation.Link;
  switch (lookup.status) {
    case "unsupported": {
      return (
        <AfferentStateRegion title={copy.common.unsupportedHeading}>
          <p>{copy.common.unsupportedBody}</p>
        </AfferentStateRegion>
      );
    }
    case "loading": {
      return <AfferentStateRegion title={copy.detail.loading} />;
    }
    case "error": {
      return (
        <AfferentStateRegion title={copy.detail.loadErrorHeading} tone="error">
          <p>{afferentErrorText(lookup.error)}</p>
        </AfferentStateRegion>
      );
    }
    case "notFound": {
      return (
        <AfferentStateRegion title={copy.detail.notFoundHeading}>
          <p>{copy.detail.notFoundBody}</p>
          <Link href={navigation.currentLocation}>
            {copy.detail.returnToFeedback}
          </Link>
        </AfferentStateRegion>
      );
    }
    case "merged": {
      return (
        <AfferentStateRegion title={copy.detail.mergedHeading}>
          <p>{copy.detail.mergedBody}</p>
          <Link href={navigation.href.post(lookup.canonicalPostId)}>
            {copy.detail.viewCanonical}
          </Link>
        </AfferentStateRegion>
      );
    }
    case "post": {
      return <Post post={lookup.post} />;
    }
    default: {
      return assertNever(lookup);
    }
  }
}

function Post({ post }: Readonly<{ post: FeedbackPostDto }>) {
  const { copy } = useAfferentUi();
  const mutations = useFeedbackMutations();
  const subscription = usePostSubscription(post.id);
  const [editing, setEditing] = useState(false);
  const [confirmingWithdraw, setConfirmingWithdraw] = useState(false);
  const [title, setTitle] = useState(post.title);
  const [body, setBody] = useState(post.body);
  const withdrawInvoker = useRef<HTMLButtonElement>(null);
  const voteKey = feedbackMutationKey(post.id, "vote");
  const editKey = feedbackMutationKey(post.id, "edit");
  const withdrawKey = feedbackMutationKey(post.id, "withdraw");

  function closeWithdraw() {
    setConfirmingWithdraw(false);
    queueMicrotask(() => withdrawInvoker.current?.focus());
  }

  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    await mutations.editPost({
      postId: post.id,
      title: title.trim(),
      body: body.trim(),
    });
  }

  const unauthenticated = mutations.status === "unauthenticated";
  let participation = null;
  if (unauthenticated) {
    participation = (
      <AfferentStateRegion title={copy.common.signInHeading}>
        <p>{copy.detail.signInBody}</p>
      </AfferentStateRegion>
    );
  } else if (mutations.status === "ready") {
    participation = (
      <div className="afferent-post-detail__actions">
        <button
          type="button"
          onClick={() => mutations.setVote(post.id, !post.viewerHasVoted)}
          disabled={mutations.pending[voteKey] ?? false}
          aria-busy={mutations.pending[voteKey] ?? false}
        >
          {post.viewerHasVoted ? copy.detail.removeVote : copy.detail.vote}
        </button>
        {subscription.status === "ready" ? (
          <button
            type="button"
            onClick={() =>
              subscription.setSubscribed(!subscription.value?.subscribed)
            }
            disabled={subscription.pending}
            aria-busy={subscription.pending}
          >
            {subscription.value?.subscribed
              ? copy.detail.unsubscribe
              : copy.detail.subscribe}
          </button>
        ) : null}
        {post.viewerCanEdit ? (
          <button type="button" onClick={() => setEditing(true)}>
            {copy.detail.edit}
          </button>
        ) : null}
        {post.viewerCanWithdraw ? (
          <button
            ref={withdrawInvoker}
            type="button"
            onClick={() => setConfirmingWithdraw(true)}
          >
            {copy.detail.withdraw}
          </button>
        ) : null}
      </div>
    );
  }
  return (
    <article className="afferent-post-detail" data-post-id={post.id}>
      <header>
        <p className="afferent-post-detail__board">{post.board.name}</p>
        <h2>{post.title}</h2>
        <p className="afferent-post-detail__status">{post.status.label}</p>
      </header>
      <p className="afferent-post-detail__body">{post.body}</p>
      <dl className="afferent-post-detail__metadata">
        <div>
          <dt>{copy.detail.votes}</dt>
          <dd>{post.voteCount}</dd>
        </div>
        <div>
          <dt>{copy.detail.comments}</dt>
          <dd>{post.commentCount}</dd>
        </div>
        <div>
          <dt>{copy.detail.author}</dt>
          <dd>{post.author.displayName ?? copy.discussion.anonymousAuthor}</dd>
        </div>
      </dl>
      {participation}
      {mutations.errors[voteKey] ? (
        <p role="alert">{afferentErrorText(mutations.errors[voteKey]!)}</p>
      ) : null}
      {editing ? (
        <form
          className="afferent-edit-form"
          onSubmit={save}
          aria-busy={mutations.pending[editKey] ?? false}
        >
          <label>
            {copy.detail.editTitle}
            <input
              name="edit-title"
              value={title}
              onChange={(event) => setTitle(event.currentTarget.value)}
            />
          </label>
          <label>
            {copy.detail.editBody}
            <textarea
              name="edit-body"
              value={body}
              onChange={(event) => setBody(event.currentTarget.value)}
            />
          </label>
          <div className="afferent-actions">
            <button
              type="submit"
              className="afferent-button"
              disabled={mutations.pending[editKey] ?? false}
            >
              {copy.detail.saveChanges}
            </button>
            <button
              type="button"
              className="afferent-button afferent-button--secondary"
              onClick={() => setEditing(false)}
            >
              {copy.detail.returnToPost}
            </button>
          </div>
        </form>
      ) : null}
      {confirmingWithdraw ? (
        <dialog open aria-labelledby="afferent-withdraw-heading">
          <h3 id="afferent-withdraw-heading">
            {copy.detail.withdrawTitle(post.title)}
          </h3>
          <p>{copy.detail.withdrawBody}</p>
          <div className="afferent-actions">
            <button
              type="button"
              className="afferent-button afferent-button--destructive"
              disabled={mutations.pending[withdrawKey] ?? false}
              onClick={async () => {
                await mutations.withdrawPost(post.id);
                closeWithdraw();
              }}
            >
              {copy.detail.withdraw}
            </button>
            <button
              type="button"
              className="afferent-button afferent-button--secondary"
              onClick={closeWithdraw}
            >
              {copy.detail.keepFeedback}
            </button>
          </div>
        </dialog>
      ) : null}
      <AfferentDiscussion postId={post.id} />
      <AfferentPostActivity postId={post.id} />
    </article>
  );
}

"use client";

import { useSimilarPosts, type BoundedDiscoveryState } from "afferent/react.js";

import { AfferentFeedbackList } from "@/components/afferent/board/feedback-list";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  afferentErrorText,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentSimilarFeedback({
  title,
  body,
}: Readonly<{ title: string; body: string }>) {
  const state = useSimilarPosts({ title, body, debounceMs: 0 });
  return <AfferentSimilarFeedbackView state={state} />;
}

export function AfferentSimilarFeedbackView({
  state,
}: Readonly<{ state: BoundedDiscoveryState }>) {
  const { copy } = useAfferentUi();
  switch (state.status) {
    case "unsupported": {
      return null;
    }
    case "loading": {
      return (
        <AfferentStateRegion title={copy.board.loadingSimilar}>
          <p>{copy.board.similarHelp}</p>
        </AfferentStateRegion>
      );
    }
    case "empty": {
      return (
        <AfferentStateRegion title={copy.board.noSimilarHeading}>
          <p>{copy.board.noSimilarBody}</p>
        </AfferentStateRegion>
      );
    }
    case "error": {
      return (
        <AfferentStateRegion
          title={copy.board.similarErrorHeading}
          tone="error"
        >
          <p>{afferentErrorText(state.error)}</p>
        </AfferentStateRegion>
      );
    }
    case "ready": {
      return (
        <section
          className="afferent-similar"
          aria-labelledby="afferent-similar-heading"
        >
          <h3 id="afferent-similar-heading">{copy.board.similarHeading}</h3>
          <p>{copy.board.similarHelp}</p>
          <AfferentFeedbackList
            items={state.items}
            label={copy.board.similarHeading}
          />
        </section>
      );
    }
    default: {
      return assertNever(state);
    }
  }
}
